package vn.covie.inventory.application;
import com.fasterxml.jackson.databind.ObjectMapper; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.covie.auth.security.CurrentActorProvider; import vn.covie.catalog.model.*; import vn.covie.catalog.persistence.LocationVariantRepository; import vn.covie.inventory.api.dto.*; import vn.covie.inventory.model.*; import vn.covie.inventory.persistence.*; import vn.covie.merchants.security.*; import vn.covie.shared.id.UuidV7Generator; import vn.covie.shared.idempotency.IdempotencyExecutor; import vn.covie.shared.time.AppClock; import vn.covie.shared.web.*;
@Service public class InventoryAdjustmentService{
 private final CurrentActorProvider actors; private final MerchantAccessPolicy access; private final LocationVariantRepository offers; private final InventoryBalanceRepository balances; private final InventoryMovementRepository movements; private final InventoryLockService locks; private final IdempotencyExecutor idempotency; private final UuidV7Generator ids; private final AppClock clock; private final ObjectMapper mapper;
 public InventoryAdjustmentService(CurrentActorProvider actors,MerchantAccessPolicy access,LocationVariantRepository offers,InventoryBalanceRepository balances,InventoryMovementRepository movements,InventoryLockService locks,IdempotencyExecutor idempotency,UuidV7Generator ids,AppClock clock,ObjectMapper mapper){this.actors=actors;this.access=access;this.offers=offers;this.balances=balances;this.movements=movements;this.locks=locks;this.idempotency=idempotency;this.ids=ids;this.clock=clock;this.mapper=mapper;}
 public InventoryCommandResult setStock(UUID merchantId,UUID offerId,String key,SetStockRequest req){var actor=actors.currentActor().userId();return idempotency.execute(actor,"INVENTORY_SET_STOCK:"+offerId,key,req,200,InventoryCommandResult.class,()->setStockInternal(actor,merchantId,offerId,req.stockOnHand(),req.reasonCode(),req.note()));}
 public InventoryCommandResult stockIn(UUID merchantId,UUID offerId,String key,StockMovementRequest req){var actor=actors.currentActor().userId();return idempotency.execute(actor,"INVENTORY_STOCK_IN:"+offerId,key,req,200,InventoryCommandResult.class,()->moveInternal(actor,merchantId,offerId,req.quantity(),true,req.reasonCode(),req.note()));}
 public InventoryCommandResult stockOut(UUID merchantId,UUID offerId,String key,StockMovementRequest req){var actor=actors.currentActor().userId();return idempotency.execute(actor,"INVENTORY_STOCK_OUT:"+offerId,key,req,200,InventoryCommandResult.class,()->moveInternal(actor,merchantId,offerId,req.quantity(),false,req.reasonCode(),req.note()));}
 @Transactional(propagation=org.springframework.transaction.annotation.Propagation.MANDATORY,noRollbackFor=ApiException.class) public InventoryCommandResult setStockInternal(UUID actor,UUID merchantId,UUID offerId,long requested,String reason,String note){var b=lock(actor,merchantId,offerId);if(requested< b.getReservedQuantity())throw err(ErrorCode.INVENTORY_BELOW_RESERVED_QUANTITY,"Stock cannot be below reserved quantity.");long delta=requested-b.getStockOnHand();if(delta!=0){movements.save(InventoryMovementEntity.create(ids.generate(),offerId,delta>0?InventoryMovementType.ADJUSTMENT_IN:InventoryMovementType.ADJUSTMENT_OUT,Math.abs(delta),null,null,null,actor,reason,metadata(note),clock.now()));b.adjust(delta,0,clock.now());}return result(b);}
 @Transactional public InventoryCommandResult moveInternal(UUID actor,UUID merchantId,UUID offerId,long quantity,boolean inbound,String reason,String note){if(quantity<=0)throw invalid("Quantity must be positive.");var b=lock(actor,merchantId,offerId);if(!inbound&&b.getStockOnHand()-quantity<b.getReservedQuantity())throw err(ErrorCode.INSUFFICIENT_INVENTORY,"Stock cannot fall below reserved quantity.");movements.save(InventoryMovementEntity.create(ids.generate(),offerId,inbound?InventoryMovementType.STOCK_IN:InventoryMovementType.STOCK_OUT,quantity,null,null,null,actor,reason,metadata(note),clock.now()));b.adjust(inbound?quantity:-quantity,0,clock.now());return result(b);}
 private InventoryBalanceEntity lock(UUID actor,UUID merchantId,UUID offerId){LocationVariantEntity offer=offers.findUsableById(offerId).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Resource not found."));access.requireLocation(merchantId,offer.getMerchantLocationId(),MerchantCapability.MANAGE_LOCATION_OFFER);if(offer.getInventoryMode()!=InventoryMode.TRACKED)throw err(ErrorCode.INVENTORY_NOT_TRACKED,"Offer is not tracked.");return locks.lockTrackedBalances(Set.of(offerId)).getFirst();}
 private com.fasterxml.jackson.databind.JsonNode metadata(String note){return note==null?null:mapper.createObjectNode().put("note",note);}
 private InventoryCommandResult result(InventoryBalanceEntity b){return new InventoryCommandResult(b.getLocationVariantId(),b.getStockOnHand(),b.getReservedQuantity(),b.availableQuantity(),b.getVersion());}
 private static ApiException invalid(String m){return new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.UNPROCESSABLE_ENTITY,m);}private static ApiException err(ErrorCode c,String m){return new ApiException(c,HttpStatus.UNPROCESSABLE_ENTITY,m);}
}
